#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

enum {A0=0,A1=1,A2=2,A3=3,NA=4};
static const int DX[NA]={0,0,-1,1}, DY[NA]={-1,1,0,0};
typedef struct{uint32_t z[NA][3][3],o[NA][3][3];unsigned long long writes;}BPC;
typedef struct{uint64_t s;}RNG;
static uint32_t ru(RNG*r){r->s^=r->s>>12;r->s^=r->s<<25;r->s^=r->s>>27;return(uint32_t)((r->s*2685821657736338717ULL)>>32);}static int ri(RNG*r,int n){return n?(int)(ru(r)%(uint32_t)n):0;}
static int reality(const uint8_t*in,uint8_t*out,int W,int H,int a){memset(out,0,(size_t)W*H);for(int y=0;y<H;y++)for(int x=0;x<W;x++)if(in[y*W+x]){int nx=x+DX[a],ny=y+DY[a];if(nx<0||nx>=W||ny<0||ny>=H)return 0;out[ny*W+nx]=1;}return 1;}
static void observe(BPC*m,const uint8_t*in,const uint8_t*t,int W,int H,int a){for(int oy=0;oy<H;oy++)for(int ox=0;ox<W;ox++)for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){int sx=ox+dx,sy=oy+dy;if(sx<0||sx>=W||sy<0||sy>=H||!in[sy*W+sx])continue;uint32_t*p=t[oy*W+ox]?&m->o[a][dy+1][dx+1]:&m->z[a][dy+1][dx+1];(*p)++;m->writes++;}}
static float tokp(const BPC*m,int a,int dy,int dx,int shift){int k=(dy+1)*3+(dx+1);k=(k+shift+9)%9;dy=k/3-1;dx=k%3-1;uint32_t z=m->z[a][dy+1][dx+1],o=m->o[a][dy+1][dx+1];return((float)o+0.5f)/((float)(o+z)+1.0f);}
static void predict(const BPC*m,const uint8_t*in,uint8_t*out,int W,int H,int a,int shift){memset(out,0,(size_t)W*H);for(int oy=0;oy<H;oy++)for(int ox=0;ox<W;ox++){double miss=1.0;int any=0;for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){int sx=ox+dx,sy=oy+dy;if(sx<0||sx>=W||sy<0||sy>=H||!in[sy*W+sx])continue;any=1;miss*=1.0-tokp(m,a,dy,dx,shift);}double p=any?1.0-miss:0.0;out[oy*W+ox]=(uint8_t)(p>0.5);}}
static void one(uint8_t*g,int n,int pos){memset(g,0,(size_t)n);g[pos]=1;}
static int exact(const uint8_t*a,const uint8_t*b,int n){return memcmp(a,b,(size_t)n)==0;}
static double f1(const uint8_t*in,const uint8_t*p,const uint8_t*t,int n){unsigned tp=0,fp=0,fn=0;for(int i=0;i<n;i++){int pc=p[i]!=in[i],tc=t[i]!=in[i];if(pc&&tc)tp++;else if(pc&&!tc)fp++;else if(!pc&&tc)fn++;}return tp?2.0*tp/(2.0*tp+fp+fn):((fp+fn)?0.0:1.0);}
static void train(BPC*m,int epochs){uint8_t in[9],t[9];for(int e=0;e<epochs;e++)for(int a=0;a<NA;a++)for(int pos=0;pos<9;pos++){one(in,9,pos);if(reality(in,t,3,3,a))observe(m,in,t,3,3,a);}}
static int random_single(RNG*r,uint8_t*g,int W,int H,int a){for(int z=0;z<100;z++){int x=ri(r,W),y=ri(r,H);if(x+DX[a]>=0&&x+DX[a]<W&&y+DY[a]>=0&&y+DY[a]<H){one(g,W*H,y*W+x);return 1;}}return 0;}
static int separated4(RNG*r,uint8_t*g,int W,int H,int a){memset(g,0,(size_t)W*H);int n=0;for(int z=0;z<1000&&n<4;z++){int x=ri(r,W),y=ri(r,H);if(x+DX[a]<0||x+DX[a]>=W||y+DY[a]<0||y+DY[a]>=H)continue;int ok=1;for(int yy=y-1;yy<=y+1;yy++)for(int xx=x-1;xx<=x+1;xx++)if(xx>=0&&xx<W&&yy>=0&&yy<H&&g[yy*W+xx])ok=0;if(ok){g[y*W+x]=1;n++;}}return n==4;}
static int rigid2(RNG*r,uint8_t*g,int W,int H,int a){memset(g,0,(size_t)W*H);for(int z=0;z<100;z++){int x=ri(r,W-1),y=ri(r,H-1),nx=x+DX[a],ny=y+DY[a];if(nx>=0&&nx+1<W&&ny>=0&&ny+1<H){g[y*W+x]=g[y*W+x+1]=g[(y+1)*W+x]=g[(y+1)*W+x+1]=1;return 1;}}return 0;}
static int line4(RNG*r,uint8_t*g,int W,int H,int a){memset(g,0,(size_t)W*H);for(int z=0;z<100;z++){int horiz=ri(r,2);int x=ri(r,W-(horiz?3:0)),y=ri(r,H-(horiz?0:3));int ok=1;for(int k=0;k<4;k++){int sx=x+(horiz?k:0),sy=y+(horiz?0:k),nx=sx+DX[a],ny=sy+DY[a];if(nx<0||nx>=W||ny<0||ny>=H)ok=0;}if(ok){for(int k=0;k<4;k++)g[(y+(horiz?0:k))*W+x+(horiz?k:0)]=1;return 1;}}return 0;}
typedef struct{unsigned long long n,full;double f1;}Stat;static void add(Stat*s,const uint8_t*in,const uint8_t*p,const uint8_t*t,int n){s->n++;s->full+=exact(p,t,n);s->f1+=f1(in,p,t,n);}static void ps(const char*n,const Stat*s){printf("%-29s n=%llu full=%7.3f%% changeF1=%.4f\n",n,s->n,100.0*s->full/s->n,s->f1/s->n);}
static void ev(BPC*m,int W,int H,int N,uint64_t seed,const char*name,int kind,int blind,int shift){RNG r={seed};uint8_t*in=malloc(W*H),*t=malloc(W*H),*p=malloc(W*H);Stat s={0};for(int i=0;i<N;i++){int a=ri(&r,NA),ok=kind==0?random_single(&r,in,W,H,a):kind==1?separated4(&r,in,W,H,a):kind==2?rigid2(&r,in,W,H,a):line4(&r,in,W,H,a);if(!ok){i--;continue;}reality(in,t,W,H,a);predict(m,in,p,W,H,blind?0:a,shift);add(&s,in,p,t,W*H);}ps(name,&s);free(in);free(t);free(p);}
static const uint16_t TS[7][4]={{0x00F0,0x4444,0x00F0,0x4444},{0x0660,0x0660,0x0660,0x0660},{0x0270,0x0262,0x0720,0x0232},{0x0360,0x0462,0x0360,0x0462},{0x0630,0x0264,0x0630,0x0264},{0x0710,0x0226,0x0470,0x0322},{0x0740,0x0622,0x0170,0x0223}};
static int bit4(uint16_t m,int x,int y){return(m>>(y*4+x))&1;}
static int tetr(RNG*r,uint8_t*g,int W,int H,int a){memset(g,0,(size_t)W*H);for(int q=0;q<200;q++){int ty=ri(r,7),rot=ri(r,4),x=ri(r,W+4)-2,y=ri(r,H+4)-2;uint16_t m=TS[ty][rot];int ok=1,n=0;for(int sy=0;sy<4;sy++)for(int sx=0;sx<4;sx++)if(bit4(m,sx,sy)){int xx=x+sx,yy=y+sy,nx=xx+DX[a],ny=yy+DY[a];if(xx<0||xx>=W||yy<0||yy>=H||nx<0||nx>=W||ny<0||ny>=H)ok=0;n++;}if(!ok||n!=4)continue;for(int sy=0;sy<4;sy++)for(int sx=0;sx<4;sx++)if(bit4(m,sx,sy))g[(y+sy)*W+x+sx]=1;return 1;}return 0;}
static void evtetr(BPC*m,int N,uint64_t seed){int W=10,H=20;RNG r={seed};uint8_t*in=malloc(W*H),*t=malloc(W*H),*p=malloc(W*H);Stat s={0};for(int i=0;i<N;i++){int a=ri(&r,NA);if(!tetr(&r,in,W,H,a)){i--;continue;}reality(in,t,W,H,a);predict(m,in,p,W,H,a,0);add(&s,in,p,t,W*H);}ps("10x20 all 7 tetrominoes",&s);free(in);free(t);free(p);}
int main(int argc,char**argv){int epochs=argc>1?atoi(argv[1]):30;BPC m={0};train(&m,epochs);printf("BPC Tetris Minimal v0.3b | fragment-wave noisy-OR | train 3x3 single only | epochs=%d writes=%llu\n",epochs,m.writes);ev(&m,3,3,2000,1,"3x3 single",0,0,0);ev(&m,5,5,4000,2,"5x5 single UNSEEN SCALE",0,0,0);ev(&m,10,10,4000,3,"10x10 single UNSEEN SCALE",0,0,0);ev(&m,10,20,4000,4,"10x20 single UNSEEN SCALE",0,0,0);ev(&m,10,20,4000,4,"10x20 action-blind",0,1,0);ev(&m,10,20,4000,4,"10x20 fragment-shift",0,0,1);ev(&m,10,20,4000,5,"10x20 four separated",1,0,0);ev(&m,10,20,4000,6,"10x20 2x2 rigid UNSEEN",2,0,0);ev(&m,10,20,4000,7,"10x20 I-piece UNSEEN",3,0,0);evtetr(&m,10000,77);return 0;}
